styles:
.sl-page {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: linear-gradient(180deg, #f8fafc 0%, #eef2ff 100%);
  min-height: 100%;
  padding-bottom: 32px;
}

.sl-page__hero {
  background: linear-gradient(135deg, #4557a3 0%, #5b6fd6 55%, #7c8ce8 100%);
  color: #fff;
  padding: 28px 32px;
  border-radius: 0 0 20px 20px;
  margin-bottom: 24px;
  box-shadow: 0 12px 40px rgba(69, 87, 163, 0.25);
}

.sl-page__hero h1 {
  margin: 0 0 8px;
  font-size: 1.5rem;
  font-weight: 800;
}

.sl-page__hero p {
  margin: 0;
  opacity: 0.9;
  font-size: 0.9rem;
}

.sl-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 20px;
  padding: 0 24px;
  max-width: 1400px;
  margin: 0 auto;
}

.sl-card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0 4px 20px rgba(15, 23, 42, 0.06);
  transition: transform 0.2s, box-shadow 0.2s;
}

.sl-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.1);
}

.sl-card__head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 18px;
  padding-bottom: 14px;
  border-bottom: 1px solid #f1f5f9;
}

.sl-card__branch {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.sl-card__badge {
  background: #eef2ff;
  color: #4557a3;
  font-weight: 800;
  font-size: 0.75rem;
  padding: 4px 10px;
  border-radius: 8px;
}

.sl-card__title {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 700;
  color: #1e293b;
}

.sl-card__manager {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.8rem;
  color: #64748b;
  white-space: nowrap;
}

.sl-card__manager i {
  color: #94a3b8;
}

.sl-metrics {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.sl-metric__top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 6px;
}

.sl-metric__label {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #94a3b8;
}

.sl-metric__limit,
.sl-metric__used {
  font-size: 0.85rem;
  font-weight: 700;
  color: #334155;
}

.sl-metric__sub {
  font-size: 0.78rem;
  color: #64748b;
  margin-bottom: 6px;
}

.sl-metric__sub--muted {
  font-style: italic;
}

.sl-metric__remain {
  font-size: 0.78rem;
  color: #16a34a;
  margin-top: 4px;
}

.sl-bar {
  height: 8px;
  background: #f1f5f9;
  border-radius: 99px;
  overflow: hidden;
}

.sl-bar__fill {
  height: 100%;
  border-radius: 99px;
  min-width: 2%;
  transition: width 0.4s ease;
}

.sl-bar__fill--tx { background: linear-gradient(90deg, #818cf8, #6366f1); }
.sl-bar__fill--month { background: linear-gradient(90deg, #38bdf8, #0ea5e9); }
.sl-bar__fill--year { background: linear-gradient(90deg, #34d399, #10b981); }

.sl-form-section {
  margin: 32px 24px 0;
  max-width: 720px;
}
